// PROTECTED: independently AI-reviewed draft. Never import into public practice.
// Human instructional/regulatory review and all approval gates remain outstanding.
export const FINAL_07_09 = [
  {"id":"LOC-F-T07-01","tests":"T07U1","unitCode":"T07U1","module":"module-07","prompt":"A hypothetical contract calendar shows three independent tasks: title objection due on day 8; an inspection election due on day 6; and a document-delivery duty due on day 5. Today is day 4. Delivery has been completed and verified, but neither decision has been made. Which is the next unresolved deadline?","choices":["The inspection election on day 6.","The completed document delivery on day 5.","The title objection on day 8 because title always takes priority.","A single combined deadline on day 8 for all three tasks."],"correctChoice":0,"rationale":"Remove only the verified completed task from the open-action list. The earliest remaining deadline is day 6; different subject matters do not merge their periods. All dates are supplied exercise terms, not universal TREC deadlines.","source":"Texas Real Estate Commission rules","section":"§531.4; supplied contract calendar","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §531.4; supplied contract calendar"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T07U1-Q’s separate-condition tracking. Replacement requires using completion evidence and ordering the remaining independent tasks.","instructionEvidence":"module-07 T07U1, provision-based calendar"},
  {"id":"LOC-F-T07-02","tests":"T07U2","unitCode":"T07U2","module":"module-07","prompt":"Assume a valid signed amendment replaces a repair with a credit only if a named permit is issued before closing; otherwise the original repair remains required. The permit has been denied. Which status follows from the express condition?","choices":["The conditional replacement did not take effect; the original repair remains required under the stated amendment.","Every signed amendment necessarily releases the original repair regardless of its condition.","Permit denial converts the conditional credit into an unconditional payment automatically.","The original repair and credit are both unconditionally due because both appear in the file."],"correctChoice":0,"rationale":"The change has an express prerequisite and fallback. Applying them is different from assuming a narrow price reduction silently released an unrelated repair.","source":"TREC Amendment to Contract, 39-11","section":"Supplied valid amendment, express condition and fallback","sources":[{"url":"https://www.trec.texas.gov/forms/amendment","reference":"TREC Amendment to Contract, 39-11, Supplied valid amendment, express condition and fallback"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats module-07’s exact price-reduction-does-not-release-repair sentence. Replacement applies a specifically amended duty with an express failed condition and fallback.","instructionEvidence":"module-07 T07U2, actual scope of an amendment; T07U1 conditions"},
  {"id":"LOC-F-T07-03","tests":"T07U3","unitCode":"T07U3","module":"module-07","prompt":"An addendum contains a specific condition connected to financing. The main form also has a financing entry. Which method best identifies the bargain?","choices":["Read the incorporated addendum and main form together, resolving actual inconsistencies through the proper process.","The main form always overrides every incorporated addendum regardless of the actual wording.","An attachment’s later page number automatically gives it priority over every other term.","The lender’s separate approval letter replaces the buyer–seller financing terms without their agreement."],"correctChoice":0,"rationale":"An incorporated document can qualify or supplement the main form. The complete agreed set, rather than document length or lender correspondence alone, identifies the terms.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraphs 3 and 22","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraphs 3 and 22"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain whole-packet interpretation, distinct from the formative missing/inapplicable attachment cases; replace weak document-length distractor.","instructionEvidence":"module-07 T07U3, incorporation"},
  {"id":"LOC-F-T07-04","tests":"T07U1","unitCode":"T07U1","module":"module-07","prompt":"A provision requires both a timely notice and supporting documentation. A party delivers only the notice. What must be evaluated?","choices":["Whether the provision’s additional documentation requirement has been satisfied.","The notice automatically substitutes for the supporting documentation whenever it is timely.","The required documentation may be omitted solely because the other party probably already knows the reason.","The agent’s oral summary automatically satisfies an express written-support requirement."],"correctChoice":0,"rationale":"A conditional right can require more than one act. The actual notice, support, recipient, and timing requirements must be applied rather than reduced to intention alone.","source":"TREC Third Party Financing Addendum, 40-11","section":"Paragraphs 2A and 2B","sources":[{"url":"https://www.trec.texas.gov/forms/third-party-financing-addendum-0","reference":"TREC Third Party Financing Addendum, 40-11, Paragraphs 2A and 2B"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain conjunction of notice and documentary support; it is not the formative request-for-extension case. All requirements must come from the invoked actual provision.","instructionEvidence":"module-07 T07U1; assigned financing addendum 2A/2B"},
  {"id":"LOC-F-T07-05","tests":"T07U2","unitCode":"T07U2","module":"module-07","prompt":"A valid first amendment grants a $6,000 credit. A valid second amendment reduces it to $4,000 only if documented repair cost exceeds $7,000, and otherwise leaves the first credit in force. The documented cost is $6,500. Which credit does this supplied sequence retain?","choices":["$6,000.","$4,000.","$10,000.","$6,500."],"correctChoice":0,"rationale":"The condition for the second amendment’s reduction was not met. Its stated fallback retains $6,000; the two credits are not cumulative, and actual repair cost is not itself the agreed credit.","source":"TREC Amendment to Contract, 39-11","section":"Supplied valid amendment sequence and condition","sources":[{"url":"https://www.trec.texas.gov/forms/amendment","reference":"TREC Amendment to Contract, 39-11, Supplied valid amendment sequence and condition"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats SC5-B/T06U6’s mismatched signed versions. Both versions here are valid, and the task applies an agreed conditional change rather than resolving missing assent.","instructionEvidence":"module-07 T07U2, original term, agreed change, related terms"},
  {"id":"LOC-F-T07-06","tests":"T07U3","unitCode":"T07U3","module":"module-07","prompt":"A mandatory Commission addendum exists for the precise transaction purpose. An agent proposes putting the same information into a different form’s blank instead, with no applicable exception. Which §537.11 restriction is implicated?","choices":["The prohibition on adding informational items for a purpose for which the Commission has approved another mandatory form.","A rule that any existing blank makes every mandatory addendum optional.","A rule that parties may always eliminate the license holder’s form-use duty by requesting a shorter packet.","A rule that a broker’s approval changes a mandatory form into a voluntary one."],"correctChoice":0,"rationale":"Subsection (b)(6) addresses this particular substitution even where the proposed entry is informational. It is different from drafting a bespoke contingency or selecting an irrelevant attachment.","source":"Texas Real Estate Commission rules","section":"§537.11(b)(6)","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §537.11(b)(6)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T07U3-R’s inapplicable-template attachment. Replacement tests replacing an applicable mandatory addendum with another form’s informational blank.","instructionEvidence":"module-07 statute reading One event, different sources; module-01 T01U5"},
  {"id":"LOC-F-T07-07","tests":"T07U1","unitCode":"T07U1","module":"module-07","prompt":"A hypothetical protection expires three calendar days before the contractual closing date. A valid amendment moves closing from August 20 to August 25 and leaves that relative formula unchanged. What date results from the supplied formula?","choices":["August 22.","August 17.","August 25.","August 28."],"correctChoice":0,"rationale":"A deadline expressly defined relative to closing moves when its specified closing-date input changes: August 25 minus three calendar days is August 22. This is not a claim that every independent fixed-date protection moves.","source":"Texas Real Estate Commission rules","section":"§531.4; supplied relative-deadline formula and valid amendment","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §531.4; supplied relative-deadline formula and valid amendment"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the taught fixed protection not automatically extended by later closing. Replacement tests a genuinely dependent deadline whose stated input did change.","instructionEvidence":"module-07 T07U1–U2, identify actual triggers and dependent dates"},
  {"id":"LOC-F-T07-08","tests":"T07U2","unitCode":"T07U2","module":"module-07","prompt":"For this exercise, a signed amendment reimburses an actual documented expense up to $1,000. The approved receipt is $800, but the closing draft inserts $1,000. Which correction applies the stated cap and actual-cost condition?","choices":["Use $800 for this reimbursement, because the cap is not a promise to pay more than the actual approved expense.","Keep $1,000 because a maximum is always a fixed payment.","Use $1,800 by adding the cap and the receipt.","Omit the reimbursement entirely because the receipt is below the cap."],"correctChoice":0,"rationale":"The payable amount under these supplied terms is the documented expense limited by the cap: min($800,$1,000)=$800. This differs from distributing an amendment or blindly changing every price-related number.","source":"TREC Amendment to Contract, 39-11","section":"Supplied reimbursement condition and cap","sources":[{"url":"https://www.trec.texas.gov/forms/amendment","reference":"TREC Amendment to Contract, 39-11, Supplied reimbursement condition and cap"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats module-07’s closing-officer-needs-the-signed-amendment case. Replacement requires reconciling an actual expense with a conditional cap.","instructionEvidence":"module-07 T07U2, reconcile affected figures from the actual change"},
  {"id":"LOC-F-T07-09","tests":"T07U3","unitCode":"T07U3","module":"module-07","prompt":"An agent makes a material false factual representation in the transaction. The principal knows it is false and does not disclose that knowledge. In evaluating the principal’s responsibility under §1101.805, which two facts are material?","choices":["The principal’s knowledge of the falsity and failure to disclose that knowledge.","The agent’s license alone, which necessarily immunizes the principal.","The principal’s lack of a separate commission invoice, which removes every misrepresentation issue.","The mere existence of agency, which makes every principal liable for every unknown false statement."],"correctChoice":0,"rationale":"Section 1101.805(d) identifies the party’s knowledge and failure to disclose it as conditions in its rule for a license holder’s material misrepresentation. The question supplies those facts rather than assuming automatic liability from agency alone.","source":"Texas Occupations Code Chapter 1101","section":"§1101.805(d)","sources":[{"url":"https://tcss.legis.texas.gov/resources/OC/htm/OC.1101.htm","reference":"Texas Occupations Code Chapter 1101, §1101.805(d)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original duplicates the source exercise’s permitted-document-use versus prohibited legal-effect advice. Replacement tests the expressly taught allocation of misrepresentation responsibility to a knowing principal.","instructionEvidence":"module-07 T07U3, adapted misrepresentation allocation"},
  {"id":"LOC-F-T07-10","tests":"T07U1","unitCode":"T07U1","module":"module-07","prompt":"For this hypothetical, a counsel-prepared condition requires the buyer to receive at least $75,000 of net proceeds from another sale. That sale closes, but the final proceeds received are $68,000. Which stated condition remains unsatisfied on those facts?","choices":["Receipt of the required minimum net proceeds.","Completion of the other closing, which the facts say has already occurred.","The buyer’s general expectation that the other sale would close.","A universal rule that any completed sale necessarily supplies $75,000."],"correctChoice":0,"rationale":"The specified condition concerns a minimum amount actually received, not simply the occurrence of another closing. The question does not invent that dollar requirement for a TREC form or determine an automatic remedy.","source":"Texas Real Estate Commission rules","section":"§531.4; supplied counsel-prepared condition","sources":[{"url":"https://www.trec.texas.gov/agency-information/rules-and-laws/trec-rules","reference":"Texas Real Estate Commission rules, §531.4; supplied counsel-prepared condition"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the abstract sale-of-other-property administration/prior-lender-delay lesson. Replacement distinguishes completed sale from a specific unmet proceeds threshold.","instructionEvidence":"module-07 T07U1, actual other-sale condition and evidence"},
  {"id":"LOC-F-T07-11","tests":"T07U2","unitCode":"T07U2","module":"module-07","prompt":"Assume a valid signed amendment restores an election only after an additional agreed payment is delivered. The amendment is signed, but the payment has not been delivered. Which status accurately applies the express prerequisite?","choices":["A restoration agreement exists, but satisfaction of its stated payment prerequisite has not been established.","Signing alone necessarily satisfies a separate delivery condition.","The election was restored before the amendment because one party requested it.","The missing payment proves no signed amendment exists at all."],"correctChoice":0,"rationale":"The facts establish an agreement but not its stated performance prerequisite. This is different from an unsigned request that never became an amendment. No universal reinstatement rule or deadline is inferred.","source":"TREC Amendment to Contract, 39-11","section":"Supplied valid conditional restoration agreement","sources":[{"url":"https://www.trec.texas.gov/forms/amendment","reference":"TREC Amendment to Contract, 39-11, Supplied valid conditional restoration agreement"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the request-is-not-an-extension branch. Replacement supplies assent and tests the separate performance condition of the agreed restoration.","instructionEvidence":"module-07 T07U1–U2, conditions and scope of agreed modifications"},
  {"id":"LOC-F-T07-12","tests":"T07U3","unitCode":"T07U3","module":"module-07","prompt":"A base agreement and incorporated exhibit both identify Tract A. A separate marketing brochure illustrates Tracts A and B but was expressly excluded from the agreed documents. Which packet supports the agreed property identification?","choices":["The base agreement and incorporated Tract A exhibit, without silently adding Tract B from the excluded brochure.","The brochure because marketing illustrations automatically control over an incorporated exhibit.","Both tracts because receiving a brochure necessarily incorporates all its contents.","Whichever description the agent last opened, regardless of the incorporation record."],"correctChoice":0,"rationale":"The stipulated document status identifies the agreed set. The brochure is not missing contract text to be reconstructed; it is expressly excluded material that should not silently enlarge the bargain.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraphs 2 and 22; supplied incorporation/exclusion facts","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraphs 2 and 22; supplied incorporation/exclusion facts"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T06U2-Q’s missing attachment. Replacement supplies the complete incorporated set and a specifically excluded competing document, testing exclusion rather than missing evidence.","instructionEvidence":"module-07 T07U3, incorporation and actual packet"},
  {"id":"LOC-F-T08-01","tests":"T08U3","unitCode":"T08U3","module":"module-08","prompt":"For an illustrative interest-only note, monthly interest is exactly $800 and equals principal × 4.8% ÷ 12. No other charge is included. Which principal produces that payment?","choices":["$200,000.","$16,666.67.","$9,600.","$240,000."],"correctChoice":0,"rationale":"The monthly rate is 0.048/12=0.004. Principal=$800/0.004=$200,000. The unknown is the balance, not the monthly payment; fees and compounding conventions are expressly excluded.","source":"CFPB Regulation Z, 12 CFR § 1026.38","section":"§1026.38(b)–(c); supplied formula","sources":[{"url":"https://www.consumerfinance.gov/rules-policy/regulations/1026/38/","reference":"CFPB Regulation Z, 12 CFR § 1026.38, §1026.38(b)–(c); supplied formula"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original duplicates the taught $120,000/6% monthly interest example by changing the balance. Replacement solves the inverse problem from a payment and a supplied rate formula.","instructionEvidence":"module-08 T08U3, transparent note arithmetic"},
  {"id":"LOC-F-T08-02","tests":"T08U3","unitCode":"T08U3","module":"module-08","prompt":"A note’s introductory stage required $900 interest-only payments. The stated schedule now moves to a payment containing $900 interest and $250 principal. Ignoring other charges, what payment does the new stage require?","choices":["$1,150.","$900.","$650.","$250."],"correctChoice":0,"rationale":"The new scheduled payment includes both components: $900+$250=$1,150. An earlier interest-only amount does not remain the full required payment after an expressly scheduled change.","source":"CFPB Regulation Z, 12 CFR § 1026.38","section":"§1026.38(b)–(c); supplied staged payment schedule","sources":[{"url":"https://www.consumerfinance.gov/rules-policy/regulations/1026/38/","reference":"CFPB Regulation Z, 12 CFR § 1026.38, §1026.38(b)–(c); supplied staged payment schedule"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the taught interest-only principal-unchanged conclusion. Replacement applies a payment-stage change with explicit principal and interest components.","instructionEvidence":"module-08 T08U3, payment changes and structures"},
  {"id":"LOC-F-T08-03","tests":"T08U2","unitCode":"T08U2","module":"module-08","prompt":"An entity owns the loan, another collects payments as servicer, and a third holds a contractual trustee role. Which error would obscure the actual structure?","choices":["Treating all three roles as necessarily identical in every transaction.","Identifying the servicer as payment collector without assuming it owns the debt.","Identifying the contractual trustee separately from the debt owner.","Using the note and security instrument to establish each role."],"correctChoice":0,"rationale":"Mortgagee, servicer, and trustee functions can be held by different persons. The actual documents and statutory definitions determine the roles.","source":"Texas Property Code Chapter 51","section":"§ 51.0001(3)–(4); § 51.0075","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.51.htm","reference":"Texas Property Code Chapter 51, § 51.0001(3)–(4); § 51.0075"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain the three-role distinction. The original positive acts are not answer errors under its error-identification stem; these alternatives keep the contrasting roles relevant.","instructionEvidence":"module-08 T08U2; §§51.0001 and 51.0075"},
  {"id":"LOC-F-T08-04","tests":"T08U4","unitCode":"T08U4","module":"module-08","prompt":"For this exercise, a security covenant requires uninterrupted insurance through the stipulated payoff on July 15, inclusive. On June 20 the file contains a policy covering through June 30, inclusive, with no renewal or extension evidence. Which interval still lacks evidence of the required coverage?","choices":["July 1 through July 15.","June 20 through June 30.","Only July 15, because the payoff date creates all earlier coverage automatically.","No interval, because a policy valid today necessarily establishes coverage through any later payoff."],"correctChoice":0,"rationale":"The supplied policy establishes coverage through June 30. The covenant continues through July 15, so evidence for July 1–15 remains outstanding. This is a coverage-period comparison, not a finding that insurance will actually lapse or a prediction of enforcement.","source":"Texas Property Code Chapter 51","section":"§51.002, security-instrument framework; supplied covenant and coverage dates","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.51.htm","reference":"Texas Property Code Chapter 51, §51.002, security-instrument framework; supplied covenant and coverage dates"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T04U4-R’s paid-debt/uncleared-lien example. An initial replacement was also too close to the teaching’s current-payments/lapsed-insurance sentence. This final replacement instead identifies a future documentary coverage gap from two different specified intervals.","instructionEvidence":"module-08 T08U4, actual collateral-protection covenant and supporting evidence"},
  {"id":"LOC-F-T08-05","tests":"T08U5","unitCode":"T08U5","module":"module-08","prompt":"Assume §5.016 applies and no exception or safe harbor is available. A seller gives the required recorded-lien notice five days before signing the binding sale contract and ten days before conveyance. Which timing issue must be identified?","choices":["The notice precedes the earlier binding-contract event by only five days, short of the stated seven-day advance requirement.","Ten days before conveyance always satisfies the rule regardless of an earlier binding contract.","The rule measures seven days after closing, so neither preclosing date matters.","A recorded lien makes the contract date irrelevant to every notice requirement."],"correctChoice":0,"rationale":"Section 5.016(a) measures advance notice from the earlier of the specified conveyance or binding-contract event. The supplied facts remove exceptions and establish a shortfall at that earlier event.","source":"Texas Property Code Chapter 5","section":"§5.016(a)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.016(a)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the seller-status-does-not-eliminate-lending-rules scenario. Replacement tests the earlier-of-two-events notice trigger expressly taught in this unit.","instructionEvidence":"module-08 T08U5, residential conveyance while recorded lien remains"},
  {"id":"LOC-F-T08-06","tests":"T08U6","unitCode":"T08U6","module":"module-08","prompt":"In this §51.003 exercise, the debt is $220,000, the foreclosure sale price is $170,000, and the court-determined fair market value is $190,000. Assume no other adjustments. After the stated fair-market-value offset, what deficiency remains?","choices":["$30,000.","$50,000.","$20,000.","$220,000."],"correctChoice":0,"rationale":"The initial debt-minus-sale difference is $50,000. The $20,000 excess of fair market value over sale price offsets it, leaving $30,000. Actual statutory qualifications and court findings are supplied for the exercise, not assumed in a real file.","source":"Texas Property Code Chapter 51","section":"§51.003(b)–(c)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.51.htm","reference":"Texas Property Code Chapter 51, §51.003(b)–(c)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original exactly repeats SC3-E’s lien release versus personal debt forgiveness. Replacement uses the distinct judicial fair-market-value offset after foreclosure.","instructionEvidence":"module-08 T08U6, §51.003 deficiency and fair-market-value analysis"},
  {"id":"LOC-F-T08-07","tests":"T08U7","unitCode":"T08U7","module":"module-08","prompt":"For this priority exercise, the only competing liens are a Texas ad valorem tax lien and an ordinary deed-of-trust lien on the same real property; no statutory exception applies. The deed of trust was recorded earlier. Which rule prevents treating recording order alone as decisive?","choices":["Tax Code §32.05 gives the tax lien the stated statutory priority over the ordinary deed-of-trust lien.","The earlier deed of trust always defeats every later statutory tax lien.","The agent’s discovery order determines priority when the recording dates differ.","A tax lien has priority only if the mortgage lender voluntarily agrees."],"correctChoice":0,"rationale":"The statute supplies special priority for the stated tax lien. The question excludes exceptions and does not generalize the result to every federal or other lien category.","source":"Texas Tax Code Chapter 32","section":"§32.05(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/TX/pdf/TX.32.pdf","reference":"Texas Tax Code Chapter 32, §32.05(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original negative stem asks what fact alone does not establish priority; more than one isolated fact may be insufficient. Replacement asks a positive, specific statutory-priority application.","instructionEvidence":"module-08 T08U7, annual attachment and statutory tax priority"},
  {"id":"LOC-F-T08-08","tests":"T08U8","unitCode":"T08U8","module":"module-08","prompt":"A borrower obtains an FHA-insured loan from an approved private lender. The borrower says FHA insurance means the federal government, rather than the borrower, now owes the monthly note payments. Which distinction corrects the claim?","choices":["Mortgage insurance protects the lender against specified loss; it does not replace the borrower’s repayment promise.","Federal insurance automatically discharges the borrower’s debt after closing.","FHA insurance makes every mortgage a direct cash loan from the government to the borrower.","Private lenders cannot originate any federally insured mortgage."],"correctChoice":0,"rationale":"An insured mortgage and the borrower’s note obligation are different parts of the financing structure. Federal insurance of the mortgage does not itself make the borrower’s debt disappear.","source":"Consumer Financial Protection Bureau, mortgage insurance explanation","section":"CFPB, Does mortgage insurance protect the lender or the borrower?; FHA loan subsection; supplied note obligation","sources":[{"url":"https://www.consumerfinance.gov/ask-cfpb/what-is-mortgage-insurance-and-how-does-it-work-en-1953/","reference":"Does mortgage insurance protect the lender or the borrower?; Federal Housing Administration (FHA) loan"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats formative T08U8-Q and SC3-D’s program-eligibility-does-not-guarantee-approval decision. Replacement tests insurance versus borrower debt in an already originated loan.","instructionEvidence":"module-08 T08U8, conventional credit and federal insurance"},
  {"id":"LOC-F-T08-09","tests":"T08U9","unitCode":"T08U9","module":"module-08","prompt":"A creditor evaluates a covered loan’s ability-to-repay requirements. Which information is relevant rather than treating collateral value as the only concern?","choices":["The applicable repayment factors and verified financial information required by the rule.","Collateral value alone, without the repayment factors required for the covered loan.","Only the borrower’s stated income, with no required verification of financial information.","Only the loan’s initial payment, ignoring other repayment factors the applicable rule requires."],"correctChoice":0,"rationale":"Regulation Z’s ability-to-repay provision addresses specified financial factors and verification for covered transactions. Collateral value alone is not the complete required analysis.","source":"CFPB Regulation Z, 12 CFR § 1026.43","section":"§ 1026.43(c)","sources":[{"url":"https://www.consumerfinance.gov/rules-policy/regulations/1026/43/","reference":"CFPB Regulation Z, 12 CFR § 1026.43, § 1026.43(c)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain covered-loan repayment-factor test and remove exterior-appearance distractor.","instructionEvidence":"module-08 T08U9; §1026.43(c)"},
  {"id":"LOC-F-T08-10","tests":"T08U10","unitCode":"T08U10","module":"module-08","prompt":"A settlement-service provider pays for actual services but adds an amount attributable to referral value. Which part of the arrangement creates a separate RESPA concern?","choices":["The referral-based compensation cannot be justified merely by labelling the whole payment a service fee.","Every payment for any actual service is automatically prohibited.","An invoice for actual services permits an additional referral-value increment without further analysis.","The full combined amount necessarily becomes reasonable service compensation merely because some services were performed."],"correctChoice":0,"rationale":"Regulation X distinguishes permissible actual-service compensation from referral payments and unearned fees. The substance and reasonable relationship to services must be evaluated.","source":"CFPB Regulation X, 12 CFR § 1024.14","section":"§ 1024.14(g)","sources":[{"url":"https://www.consumerfinance.gov/rules-policy/regulations/1024/14/","reference":"CFPB Regulation X, 12 CFR § 1024.14, § 1024.14(g)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain: unlike the portal practice/SC3 that identifies no actual service, this case supplies actual services and a separate referral-value increment. §1024.14(g) addresses that economically different arrangement.","instructionEvidence":"module-08 T08U10; §1024.14(g)","integrationReview":"Root strengthened retained distractors; same assessment decision and correct answer."},
  {"id":"LOC-F-T08-11","tests":"T08U9","unitCode":"T08U9","module":"module-08","prompt":"A creditor’s adverse treatment is based on a prohibited characteristic. The applicant has substantial assets. Which principle governs?","choices":["Protected-basis restrictions apply independently of whether the applicant appears wealthy.","A substantial asset balance automatically waives the applicant’s protected-basis restrictions.","Protected-basis restrictions apply only after the applicant proves low income.","A seller’s consent can authorize a creditor’s prohibited-basis treatment of the buyer."],"correctChoice":0,"rationale":"Regulation B prohibits discrimination on a prohibited basis in any aspect of a credit transaction. Asset level is not a blanket removal of those protections.","source":"CFPB Regulation B, 12 CFR § 1002.4","section":"§ 1002.4(a)","sources":[{"url":"https://www.consumerfinance.gov/rules-policy/regulations/1002/4/","reference":"CFPB Regulation B, 12 CFR § 1002.4, § 1002.4(a)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain asset level as a nonexception to the rule; formative concerns discouragement before application.","instructionEvidence":"module-08 T08U9; §1002.4(a)"},
  {"id":"LOC-F-T08-12","tests":"T08U1","unitCode":"T08U1","module":"module-08","prompt":"A borrower’s payment default gives rise to possible enforcement under a deed of trust. Which statement avoids confusing a contractual trigger with completed foreclosure?","choices":["Default can begin an enforcement analysis, but the required instrument and statutory steps still must occur.","A payment default is itself a completed trustee’s sale without the remaining required steps.","A contractual acceleration provision necessarily eliminates all applicable statutory notice requirements.","A listing of the collateral automatically establishes that the required foreclosure procedure has been completed."],"correctChoice":0,"rationale":"A trigger and the completed enforcement event are distinct. The applicable notices, authority, timing, and sale requirements require proper analysis.","source":"Texas Property Code Chapter 51","section":"§ 51.002","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.51.htm","reference":"Texas Property Code Chapter 51, § 51.002"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain the distinction between trigger and completed enforcement, but remove irrelevant document-name confusion. The final does not reproduce the formative listing-as-automatic-stay case.","instructionEvidence":"module-08 T08U1 and U6; §51.002"},
  {"id":"LOC-F-T09-01","tests":"T09U5","unitCode":"T09U5","module":"module-09","prompt":"An instrument is properly recorded in the correct county. Under § 13.002, which notice consequence is identified?","choices":["Notice to all persons of the instrument’s existence.","Notice only to the persons individually named in the instrument.","An automatic conclusion that every statement in the recorded instrument is true.","A warranty by the county that the grantor had perfect title."],"correctChoice":0,"rationale":"Section 13.002 states the notice effect. It should not be expanded into a certification of authenticity, authority, title quality, or permissible use.","source":"Texas Property Code Chapter 13","section":"§ 13.002","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.13.htm","reference":"Texas Property Code Chapter 13, § 13.002"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain the affirmative statutory notice consequence. Formative and source exercise reject a validation guarantee; this asks which legal consequence proper recording actually supplies.","instructionEvidence":"module-09 T09U5; §13.002","integrationReview":"Root strengthened retained distractors; same assessment decision and correct answer."},
  {"id":"LOC-F-T09-02","tests":"T09U2","unitCode":"T09U2","module":"module-09","prompt":"A deed is signed by a person lawfully authorized in writing to act for the owner and is delivered as required. Which statutory conveyance feature is directly relevant?","choices":["The recognized role of an authorized agent’s written subscription and delivery.","A requirement that any available witness may replace the owner’s authorized signer.","A rule that signing without required delivery necessarily completes every conveyance.","A rule that the authority may always be inferred solely from possession of the deed."],"correctChoice":0,"rationale":"Section 5.021 addresses written, subscribed, delivered conveyance and authorized agents. The actual authority and remaining legal requirements must still be established.","source":"Texas Property Code Chapter 5","section":"§ 5.021","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, § 5.021"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain written authorized execution plus delivery, unlike the formative deed left in a drawer; T06-12 has been replaced so the bank no longer repeats authorized-signature application there.","instructionEvidence":"module-09 T09U2; §5.021"},
  {"id":"LOC-F-T09-03","tests":"T09U1","unitCode":"T09U1","module":"module-09","prompt":"Assume every described deed is valid and delivered. Vega initially owns the whole tract, conveys a 30% undivided interest to Hale, then conveys a 20% undivided interest in the original whole tract to Reed. Vega makes no other conveyance. What interest remains with Vega?","choices":["50% of the whole tract.","56% of the whole tract.","70% of the whole tract.","20% of the whole tract."],"correctChoice":0,"rationale":"The second deed is expressly 20% of the original whole, not 20% of Vega’s remaining 70%. Subtracting 30% and 20% from the whole leaves 50%. This is reconstruction from stipulated valid transfers, not a title opinion about unresolved instruments.","source":"Texas Property Code Chapter 5","section":"§5.001; supplied valid conveyances and denominators","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §5.001; supplied valid conveyances and denominators"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T09U2-R’s unexplained grantor ownership problem. Replacement reconstructs a complete chain of two expressly valid partial transfers.","instructionEvidence":"module-09 T09U1, chain and ownership classification; module-02 undivided shares"},
  {"id":"LOC-F-T09-04","tests":"T09U3","unitCode":"T09U3","module":"module-09","prompt":"A claimant relies on continuous possession, but an adverse suit to recover the property interrupted the period being asserted. Which separately defined requirement in §16.021 is directly implicated?","choices":["Peaceable possession, which the definition ties to continuity not interrupted by an adverse recovery suit.","Only whether the claimant made an occasional site visit.","An automatic title transfer to the claimant merely because litigation began.","A rule that paying property taxes prevents any suit from interrupting possession."],"correctChoice":0,"rationale":"Section 16.021(3) defines peaceable possession in terms of continuous possession not interrupted by an adverse suit to recover the property. The question does not compute a limitations period or decide ownership.","source":"Texas Civil Practice and Remedies Code Chapter 16","section":"§16.021(3)","sources":[{"url":"https://tcss.legis.texas.gov/resources/CP/htm/CP.16.htm","reference":"Texas Civil Practice and Remedies Code Chapter 16, §16.021(3)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats T09U3-Q’s missing actual/visible possession. Replacement tests the different peaceable-possession element and interruption by an adverse suit.","instructionEvidence":"module-09 T09U3, statutory definitions and clocks"},
  {"id":"LOC-F-T09-05","tests":"T09U4","unitCode":"T09U4","module":"module-09","prompt":"An owner dies intestate. No survivorship or other nonprobate transfer is assumed. Which §101.001 route identifies the recipients of the owner’s estate, without determining their individual shares?","choices":["The owner’s heirs at law under the applicable intestate-succession framework.","A named devisee under a will that does not exist in these facts.","The personal representative as individual beneficial owner merely because of the appointment.","The state automatically, because every intestate estate escheats regardless of heirs."],"correctChoice":0,"rationale":"Section 101.001(b) addresses property left by a person who dies intestate. Identifying heirs and shares still requires the applicable succession facts and law; administration and debt qualifications are not erased.","source":"Texas Estates Code Chapter 101","section":"§101.001(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/ES/htm/ES.101.htm","reference":"Texas Estates Code Chapter 101, §101.001(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original exactly repeats T09U4-R’s vesting-does-not-remove-debts/admin branch. Replacement distinguishes intestate recipients from devisees, representative capacity, and escheat.","instructionEvidence":"module-09 T09U4, death, probate and intestacy"},
  {"id":"LOC-F-T09-06","tests":"T09U6","unitCode":"T09U6","module":"module-09","prompt":"An owner’s policy and a lender’s policy protect different insured interests. What should the buyer avoid assuming from the lender’s policy alone?","choices":["That it necessarily provides the buyer the same coverage as an owner’s policy.","That title coverage can identify an insured interest.","That policy terms and exceptions should be reviewed.","That the purchase contract can address who provides an owner’s policy."],"correctChoice":0,"rationale":"The insured interest and actual policy matter. A lender’s protection is not automatically the purchaser’s owner coverage; the contract’s title-policy provisions should be reviewed.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 6A","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 6A"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain distinct insured interests in owner and lender policies. The practice instead confuses commitment with final policy and examines an excepted easement; no duplicate owner-versus-lender case was located.","instructionEvidence":"module-09 T09U6, owner and lender policies"},
  {"id":"LOC-F-T09-07","tests":"T09U2","unitCode":"T09U2","module":"module-09","prompt":"A proposed conveyance document grants only the signer’s described interest rather than guaranteeing a broader estate. Which review is essential?","choices":["The operative granting and warranty language together with the grantor’s actual interest.","The assumption that every deed contains identical warranties.","The belief that any recorded instrument guarantees every prior owner’s conduct.","The purchaser’s preferred label regardless of the text."],"correctChoice":0,"rationale":"Deed language and the estate conveyed must be read accurately. Recording or a generic deed label does not make all instruments equivalent in scope or warranties.","source":"Texas Property Code Chapter 5","section":"§§ 5.001 and 5.022–5.023","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, §§ 5.001 and 5.022–5.023"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain scope of operative granting/warranty language, not a guarantee from deed labels. The practice concerns missing grantor ownership; this question does not say that recordation or a quitclaim label creates a particular warranty.","instructionEvidence":"module-09 T09U2, warranty distinctions"},
  {"id":"LOC-F-T09-08","tests":"T09U5","unitCode":"T09U5","module":"module-09","prompt":"A person receives land as a gift and discovers an earlier unrecorded conveyance. Why does § 13.001 not automatically give that gift recipient the protection afforded to a purchaser for value without notice?","choices":["The statute distinguishes a subsequent purchaser who pays valuable consideration from one who does not.","Every unrecorded instrument is void against every later recipient, including a gift recipient.","A gift is necessarily valuable consideration whenever the recipient later pays property taxes.","The statute protects gift recipients only because they did not negotiate a purchase price."],"correctChoice":0,"rationale":"Section 13.001(b) makes the unrecorded instrument binding on a subsequent purchaser who does not pay valuable consideration or who has notice. The value-and-notice conditions cannot be omitted from the analysis.","source":"Texas Property Code Chapter 13","section":"§ 13.001(a)–(b)","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.13.htm","reference":"Texas Property Code Chapter 13, § 13.001(a)–(b)"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"RETAIN","reviewReason":"Retain gift recipient/no valuable consideration. The teaching worked case concerns actual notice of an earlier deed, a different statutory disqualifier from purchaser-for-value protection.","instructionEvidence":"module-09 T09U5; §13.001(a)–(b)"},
  {"id":"LOC-F-T09-09","tests":"T09U3","unitCode":"T09U3","module":"module-09","prompt":"A trustee’s deed follows a foreclosure sale, while another document reflects a voluntary owner-to-buyer deed. What distinguishes the claimed source of transfer?","choices":["One depends on the security-enforcement process; the other on the owner’s voluntary conveyance.","Both necessarily depend on voluntary consent from the current owner at the moment of sale.","Both necessarily arise through inheritance because a trustee is involved.","A voluntary conveyance eliminates the need to establish the owner’s authority and required delivery."],"correctChoice":0,"rationale":"The transfer mechanisms differ and require their respective documents and legal analysis. The title review should identify the actual source rather than merge all deeds into one process.","source":"Texas Property Code Chapter 51","section":"§ 51.002; Property Code § 5.021","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.51.htm","reference":"Texas Property Code Chapter 51, § 51.002; Property Code § 5.021"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain distinction between transfer mechanisms with plausible alternative mechanisms, removing seller-disclosure distractor.","instructionEvidence":"module-09 T09U2–U3"},
  {"id":"LOC-F-T09-10","tests":"T09U6","unitCode":"T09U6","module":"module-09","prompt":"A buyer receives an abstract summarizing recorded instruments. The supplied engagement is only for a records summary and contains no title-insurance policy or indemnity promise. The buyer asks to collect an insurance claim under that abstract. Which document distinction matters?","choices":["A records abstract is not itself the missing title-insurance policy or a stipulated promise of insured indemnity.","Every abstract necessarily is an owner’s policy merely because it concerns title.","A list of recorded instruments automatically guarantees payment for every defect appearing in them.","An abstract necessarily replaces all commitment requirements and exceptions."],"correctChoice":0,"rationale":"The scenario supplies the limited engagement and absence of insurance. It tests instrument function, not whether an abstractor could face some different negligence or contract claim.","source":"TREC One to Four Family Residential Contract (Resale), 20-19","section":"Paragraph 6A, owner policy; supplied records-summary engagement","sources":[{"url":"https://www.trec.texas.gov/forms/one-four-family-residential-contract-resale","reference":"TREC One to Four Family Residential Contract (Resale), 20-19, Paragraph 6A, owner policy; supplied records-summary engagement"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REWRITE","reviewReason":"Original repeats the commitment-exception/intended-use exercise. Replacement distinguishes an abstract from insurance and expressly avoids adding a liability doctrine.","instructionEvidence":"module-09 T09U6, abstracts and insurance are different evidence/products"},
  {"id":"LOC-F-T09-11","tests":"T09U4","unitCode":"T09U4","module":"module-09","prompt":"A proposed estate sale requires documents showing the representative’s authority. Why is the representative’s personal ownership of another property irrelevant to that proof?","choices":["Authority to administer this estate is distinct from the representative’s personal property ownership.","Owning personal property automatically establishes appointment and authority for this decedent’s estate.","Approval of the sale price by the buyer replaces the representative’s authority evidence.","Being named in any unrelated deed establishes authority to sign for every estate."],"correctChoice":0,"rationale":"The relevant authority comes from the estate framework and required documents. Personal assets do not substitute for authority to act for the decedent’s estate.","source":"Texas Estates Code Chapter 101","section":"§ 101.003","sources":[{"url":"https://tcss.legis.texas.gov/resources/ES/htm/ES.101.htm","reference":"Texas Estates Code Chapter 101, § 101.003"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain representative capacity versus personal ownership, but keep alternatives within authority evidence.","instructionEvidence":"module-09 T09U4; §101.003"},
  {"id":"LOC-F-T09-12","tests":"T09U1","unitCode":"T09U1","module":"module-09","prompt":"A purchaser receives a deed subject to a specifically retained interest. Which record should be used to identify what changed ownership?","choices":["The deed’s operative conveyance and reservation terms in the relevant title context.","The fact of full payment, without reading the express reservation.","A listing’s broader ownership description, even if inconsistent with the operative deed.","The assumption that recording deletes every reservation written into the recorded instrument."],"correctChoice":0,"rationale":"The estate transferred is determined from the operative instrument and law. Consideration and marketing language do not erase a reservation.","source":"Texas Property Code Chapter 5","section":"§ 5.001","sources":[{"url":"https://tcss.legis.texas.gov/resources/PR/htm/PR.5.htm","reference":"Texas Property Code Chapter 5, § 5.001"}],"assessmentRole":"PROTECTED_FINAL","reviewDisposition":"REPAIR","reviewReason":"Retain completed deed’s actual reservation. This is not the teaching’s unresolved seller promise of an estate the seller may not own; operative transfer terms are supplied.","instructionEvidence":"module-09 T09U1–U2; §5.001"},
];
